function extract(filePath) {
  const buf = fs.readFileSync(filePath);
  const phoff = Number(buf.readBigUInt64LE(0x20));
  const phentsize = buf.readUInt16LE(0x36);
  const phnum = buf.readUInt16LE(0x38);

  const result = {};

  for (let i = 0; i < phnum; i++) {
    const p_off = phoff + i * phentsize;
    const p_type = buf.readUInt32LE(p_off);
    if (p_type === 1) { // PT_LOAD
      const p_offset = Number(buf.readBigUInt64LE(p_off + 8));
      const p_vaddr = Number(buf.readBigUInt64LE(p_off + 16));
      const p_filesz = Number(buf.readBigUInt64LE(p_off + 32));
      const p_memsz = Number(buf.readBigUInt64LE(p_off + 40));

      // Read from file buffer for filesz, and pad with 0 up to memsz if needed
      // But wait, are we extracting 32-bit integers (4 bytes) at 4-byte aligned addresses?
      for (let offset = 0; offset < p_filesz; offset += 4) {
